import java.util.Map;
import java.util.TreeMap;

public class Main {
    public static void main(String[] args) {
        TreeMap<Integer, String> tickets = new TreeMap<>();
        tickets.put(65, "Senior");
        tickets.put(0, "Child");
        tickets.put(18, "Adult");
        tickets.put(13, "Teen");

        System.out.println(tickets);
        for (Map.Entry<Integer, String> entry : tickets.entrySet()) {
            System.out.println(entry.getKey() + "+ " + entry.getValue());
        }

        int[] ages = {7, 16, 70};
        for (int age : ages) {
            Integer bracket = tickets.floorKey(age);
            System.out.println("Age " + age + ": " + tickets.get(bracket));
        }

        System.out.println("First: " + tickets.firstKey());
        System.out.println("Last: " + tickets.lastKey());
        System.out.println("Ceiling of 14: " + tickets.ceilingKey(14));
        System.out.println("Floor of -5: " + tickets.floorKey(-5));
    }
}

