import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public class Main {
    public static void main(String[] args) {
        String[] words = {"cherry", "apple", "banana", "avocado", "cranberry", "blueberry"};

        Map<Character, List<String>> byLetter = new LinkedHashMap<>();
        for (String word : words) {
            char first = word.charAt(0);
            byLetter.putIfAbsent(first, new ArrayList<>());
            byLetter.get(first).add(word);
        }

        System.out.println(byLetter);
        for (Map.Entry<Character, List<String>> entry : byLetter.entrySet()) {
            System.out.println(entry.getKey() + ": " + entry.getValue().size() + " words");
        }
    }
}

