import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public class Main {
    public static void main(String[] args) {
        String[] students = {"Ana", "Ben", "Cy", "Dee", "Eli", "Fay"};
        String[] classes = {"Math", "Art", "Math", "Music", "Art", "Math"};

        Map<String, List<String>> byClass = new LinkedHashMap<>();
        for (int i = 0; i < students.length; i++) {
            byClass.putIfAbsent(classes[i], new ArrayList<>());
            byClass.get(classes[i]).add(students[i]);
        }

        for (Map.Entry<String, List<String>> entry : byClass.entrySet()) {
            System.out.println(entry.getKey() + ": " + entry.getValue());
        }
    }
}
